/* RFI-aligned prototype workflows. Business data remains local demo data. */
const supervisors=()=>globalThis.BPD_USER&&!globalThis.BPD_SIM_ACTIVE?['SPV','Superadmin'].includes(globalThis.BPD_USER.role):['Supervisor','Administrator'].includes(actor());
const quals=['Cool','Warm','Hot 1','Hot 2'];
function migrate(){db.applications=db.applications||[];db.corrections=db.corrections||[];db.config.stageSla=db.config.stageSla||{'Kebutuhan':3,'Pembahasan':5,'Persiapan':7,'Keputusan':3};db.config.workdays=db.config.workdays||'Senin-Jumat';db.config.holidays=db.config.holidays||'';db.config.timezone='Asia/Makassar';db.leads.forEach(l=>{l.grade=l.grade||'Warm';l.qualification=l.qualification||'Belum dinilai'});db.opps.forEach(o=>{o.probability=o.probability??35;o.target=o.target||'Belum ditautkan'});db.tasks.filter(t=>activityKind(t.type)==='Kunjungan').forEach(t=>{t.approval=t.approval||'Menunggu';t.approvalHistory=t.approvalHistory||[]});if(!db.rfiDemo){db.tasks.push({id:uid('T'),profile:'P3',opp:'O1',type:'Kunjungan',purpose:'Pembahasan penempatan dana',owner:owners[0],scheduled:offset(1)+'T10:00',due:offset(1)+'T17:00',status:'Terjadwal',approval:'Menunggu',approvalHistory:[]});db.rfiDemo=true;db.applications.push({id:uid('AP'),profile:'P3',opp:'O1',number:'DEMO-APP-001',product:'Deposito',source:'Input manual',updated:now(),survey:'Tidak berlaku',analysis:'Dalam proses',approval:'Belum diputuskan',disbursement:'Tidak berlaku',history:[{time:now(),actor:'Data demo',note:'Contoh status, bukan data sistem Bank'}]})}}
migrate();
function age(o){return Math.max(0,Math.floor((Date.now()-new Date(o.entered))/86400000))}function stageLimit(o){return Number(db.config.stageSla[o.stage]||db.config.aging)}function overSla(o){return o.outcome==='Aktif'&&age(o)>stageLimit(o)}
function titleBlock(title,sub,actions=''){return `<div class="intro"><div><span class="label">RELATIONSHIP WORKSPACE</span><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
function sectionToggle(title,body,open=false){return `<details class="accordion" ${open?'open':''}><summary>${title}</summary><div>${body}</div></details>`}
function labelled(name,value){return `<div><small>${name}</small><strong>${E(value||'Belum diisi')}</strong></div>`}
const originalRender=render,originalContent=renderContent,originalCheckin=checkin,originalModal=modal,originalImport=importData,originalCard=oppCard;
modal=function(title,html,handler){originalModal(title,html,f=>{if(!$('#form').checkValidity()){ $('#form').reportValidity();return false}return handler(f)})};
render=function(){originalRender();const pages=mobile?['Agenda','Leads','Peluang','Nasabah','Lainnya']:['Monitoring','Leads','Peluang','Agenda','Persetujuan','Pengajuan','Nasabah','Laporan','Notifikasi','Pengaturan'];const icons=['◈','◎','▦','◷','✓','▤','◉','↗','♧','⚙'];$('#nav').innerHTML=pages.map((n,i)=>`<button class="${navigationParent(view)===n?'active':''}" ${navigationParent(view)===n?'aria-current="page"':''} onclick="go('${n}')"><span>${icons[i]}</span>${n}${n==='Persetujuan'&&pendingApprovals().length?`<b class="navcount">${pendingApprovals().length}</b>`:''}</button>`).join('');$('#title').textContent=view;};
function pendingApprovals(){return db.tasks.filter(t=>activityKind(t.type)==='Kunjungan'&&['Menunggu','Perubahan diajukan'].includes(t.approval)&&mine(t))}
function guardVisit(t){if(activityKind(t.type)==='Kunjungan'&&t.approval!=='Disetujui')throw Error('Rencana kunjungan perlu disetujui supervisor sebelum pelaksanaan.')}
checkin=function(id,demo=false){try{guardVisit(task(id));originalCheckin(id,demo)}catch(e){toast(e.message)}};
oppCard=function(o){return originalCard(o).replace('<div class="next">',`<div class="oppmeta"><span>${o.probability??0}% probability</span>${badge(overSla(o)?'Over SLA':age(o)+' / '+stageLimit(o)+' hari')}</div><div class="next">`)};
function createLead(){modal('Lead baru',`<p class="formintro">Mulai dari identitas dan kebutuhan. Kualifikasi serta assessment dapat dilengkapi setelah kontak pertama.</p>`+field('Nama orang / perusahaan','name','','text',true)+field('Nama kontak','contact')+field('Nomor telepon','phone','','tel',true)+select('Sumber lead','source',['Input Lead','Campaign Lead','Referral Lead','Digital Lead','Existing Customer Lead'])+field('Pemberi referral (jika referral)','referral')+select('Minat produk','product',['Belum diketahui','Tabungan','Giro','Deposito','Kredit Konsumtif','Kredit Produktif','KUR'])+area('Kebutuhan awal','need')+ownerSelect()+sectionToggle('Informasi tambahan',field('Alamat','address')+field('Alamat usaha / bekerja','businessAddress')+field('Pekerjaan / bidang usaha','occupation')),f=>{if(isReferralSource(f.source)&&!f.referral.trim())throw Error('Isi pemberi referral.');let p=db.profiles.find(p=>normalize(p.phone)===normalize(f.phone));if(p)throw Error('Kontak kemungkinan sudah tercatat. Buka Lead atau Nasabah untuk membuat peluang pada data existing.');p={id:uid('P'),name:f.name,contact:f.contact,phone:f.phone,address:f.address,businessAddress:f.businessAddress,occupation:f.occupation,relation:'Prospect',owner:f.owner};db.profiles.push(p);let l={id:uid('L'),profile:p.id,owner:f.owner,source:f.source,referral:f.referral,product:f.product,need:f.need,status:'New',qualification:'Belum dinilai',grade:'Cool',created:today(),recorded:now()};db.leads.push(l);record('Buat lead',l.id,f.name);go('Lead detail',l.id)})}
function qualify(id){let l=db.leads.find(x=>x.id===id);modal('Kualifikasi lead',select('Hasil kualifikasi','qualification',['Qualified','Tidak Qualified','Perlu informasi'],l.qualification)+select('Kategori potensi','grade',quals,l.grade)+area('Customer need analysis','need',l.need,true)+area('Potensi bisnis / dasar penilaian','potential',l.potential||'',true)+select('Langkah berikutnya','decision',['Simpan kualifikasi','Lanjut opportunity','Tambah Task'])+`<p class="hint">Pilih kategori berdasarkan potensi dan kesiapan kebutuhan lead.</p>`,f=>{if(f.decision==='Lanjut opportunity'&&f.qualification!=='Qualified')throw Error('Konversi memerlukan hasil Qualified.');Object.assign(l,{qualification:f.qualification,grade:f.grade,need:f.need,potential:f.potential,status:'In qualification'});record('Kualifikasi lead',id,f.qualification+' / '+f.grade);if(f.decision==='Lanjut opportunity')setTimeout(()=>newOpp(l.profile,l.id),50);if(f.decision==='Tambah Task')setTimeout(()=>newTask(l.profile,'',l.id),50)})}
function assessment(id){let l=db.leads.find(x=>x.id===id),a=l.assessment||{};modal('Survey & assessment awal',field('Tanggal survey','date',a.date||today(),'date',true)+area('Hasil survey','survey',a.survey||'',true)+area('Informasi usaha','business',a.business||'',true)+area('Gambaran keuangan','financial',a.financial||'',true)+area('Kesimpulan assessment','conclusion',a.conclusion||'',true)+`<p class="hint">Catat sumber informasi dan kesimpulan survey secara jelas.</p>`,f=>{l.assessment={...f,actor:actor(),recorded:now()};record('Assessment lead',id,f.conclusion)})}
const originalNewOpp=newOpp;
newOpp=function(pid='',lid=''){let l=db.leads.find(x=>x.id===lid);if(l&&l.qualification!=='Qualified')return toast('Lengkapi kualifikasi Qualified sebelum konversi.');originalNewOpp(pid,lid);let form=$('#form');if(form){let b=form.querySelector('.actions');if(b)b.insertAdjacentHTML('beforebegin',field('Probability (%)','probability','35','number')+field('Target bisnis / periode terkait','target',''));let old=form.onsubmit;form.onsubmit=e=>{let v=form.elements.probability.value;if(v===''||Number(v)<0||Number(v)>100){e.preventDefault();$('#formerror').textContent='Probability harus 0-100%';return}let before=db.opps.length;old(e);if(db.opps.length>before){let o=db.opps.at(-1);o.probability=Number(v);o.target=form.elements.target.value||'Belum ditautkan';record('Parameter opportunity',o.id,o.probability+'%')}}}};
function editOpportunity(id){let o=opp(id);modal('Detail peluang bisnis',field('Nama peluang','name',o.name,'text',true)+field('Nilai indikatif (Rp)','value',o.value??'','number')+select('Basis nilai','basis',['Plafon indikatif','Penempatan dana','Total kontrak','Sekali bayar','Bulanan','Tahunan'],o.basis)+field('Probability (%)','probability',o.probability??35,'number',true)+field('Target closing','closing',o.closing,'date',true)+field('Target bisnis / periode','target',o.target||'')+area('Kebutuhan','need',o.need,true),f=>{if(Number(f.probability)<0||Number(f.probability)>100)throw Error('Probability 0-100%');Object.assign(o,{...f,probability:Number(f.probability),value:f.value===''?null:Number(f.value)});record('Update detail opportunity',id,'Probability '+o.probability+'%; target '+o.target)})}
function visitFields(t={}){return field('Tujuan aktivitas','purpose',t.purpose||'','text',true)+ownerSelect(t.owner)+field('Jadwal pelaksanaan (WITA)','scheduled',t.scheduled||offset(1)+'T09:00','datetime-local',true)+field('Deadline (WITA)','due',t.due||offset(1)+'T17:00','datetime-local',true)}
function newTask(pid='',oid='',lid=''){let ps=visible(db.profiles);modal('Tambah Task',`<label>Profil<select name="profile" ${pid?'disabled':''}>${ps.map(p=>`<option value="${p.id}" ${p.id===pid?'selected':''}>${E(p.name)}</option>`).join('')}</select></label>`+select('Jenis aktivitas','type',['Telepon','Kunjungan','Meeting','Cek dokumen'])+visitFields({owner:opp(oid)?.owner||profile(pid)?.owner})+sectionToggle('Khusus meeting',field('Peserta meeting','participants')+area('Agenda meeting','meetingAgenda'))+`<p class="hint">Rencana kunjungan masuk antrean persetujuan supervisor. Telepon dan task lain langsung masuk agenda.</p>`,f=>{if(new Date(f.due)<new Date(f.scheduled))throw Error('Deadline tidak boleh sebelum jadwal.');let t={...f,id:uid('T'),profile:pid||f.profile,opp:oid,lead:lid,status:'Terjadwal'};if(activityKind(t.type)==='Kunjungan'){t.approval='Menunggu';t.approvalHistory=[{time:now(),actor:actor(),status:'Diajukan',note:'Rencana kunjungan baru'}]}db.tasks.push(t);if(oid)delete opp(oid).review;record('Rencana aktivitas',t.id,f.type+' - '+f.purpose)})}
function reschedule(id){let t=task(id);if(t.checkin)return toast('Kunjungan sudah dimulai. Gunakan koreksi data melalui supervisor.');modal('Ajukan perubahan jadwal',field('Jadwal baru (WITA)','scheduled',t.scheduled,'datetime-local',true)+field('Deadline baru (WITA)','due',t.due,'datetime-local',true)+area('Alasan perubahan','reason','',true)+`<p class="hint">${activityKind(t.type)==='Kunjungan'?'Perubahan kunjungan memerlukan persetujuan. Jadwal lama tetap terlihat sampai keputusan.':'Deadline sebelumnya tetap ada dalam riwayat.'}</p>`,f=>{if(new Date(f.due)<new Date(f.scheduled))throw Error('Deadline sebelum jadwal.');if(activityKind(t.type)==='Kunjungan'){t.pendingChange=f;t.approval='Perubahan diajukan';(t.approvalHistory||=[]).push({time:now(),actor:actor(),status:'Perubahan diajukan',note:f.reason})}else {let old=t.due;Object.assign(t,{scheduled:f.scheduled,due:f.due});record('Reschedule',id,old+' menjadi '+f.due+' / '+f.reason);return}record('Ajukan perubahan kunjungan',id,f.reason)})}
function approveVisit(id,decision){if(!supervisors())return toast('Tindakan ini memerlukan kewenangan supervisor.');let t=task(id);modal(decision==='Disetujui'?'Setujui rencana':'Kembalikan rencana',area('Catatan keputusan','note','',decision!=='Disetujui'),f=>{if(!['Menunggu','Perubahan diajukan'].includes(t.approval))throw Error('Permintaan sudah diproses');let old=t.scheduled;if(decision==='Disetujui'&&t.pendingChange){Object.assign(t,{scheduled:t.pendingChange.scheduled,due:t.pendingChange.due});delete t.pendingChange}t.approval=decision;(t.approvalHistory||=[]).push({time:now(),actor:actor(),status:decision,note:f.note,oldSchedule:old,newSchedule:t.scheduled});record('Keputusan kunjungan',id,decision+' / '+f.note)})}
function resubmitVisit(id){let t=task(id);delete t.pendingChange;t.approval='Menunggu';(t.approvalHistory||=[]).push({time:now(),actor:actor(),status:'Diajukan ulang',note:'AO mengajukan kembali rencana'});record('Ajukan ulang',id,'Rencana kunjungan')}
function cancelTask(id){modal('Batalkan aktivitas',area('Alasan pembatalan','reason','',true),f=>{let t=task(id);t.status='Dibatalkan';t.cancelReason=f.reason;record('Batalkan aktivitas',id,f.reason)})}
const originalActivity=activityForm;
activityForm=function(id){let t=task(id);try{guardVisit(t)}catch(e){return toast(e.message)}if(activityKind(t.type)==='Kunjungan'&&!t.checkin)return toast('Check-in dahulu');if(activityKind(t.type)==='Kunjungan'&&!t.photo)return toast('Tambahkan foto kunjungan sebelum menyimpan laporan.');originalActivity(id);if(activityKind(t.type)==='Meeting'){let a=$('#form .actions');a.insertAdjacentHTML('beforebegin',field('Peserta meeting','participants',t.participants||'','text',true)+area('Agenda dan kesepakatan','meetingAgenda',t.meetingAgenda||'',true));let old=$('#form').onsubmit;$('#form').onsubmit=e=>{let form=e.target,p=form.elements.participants.value,agenda=form.elements.meetingAgenda.value;if(!p||!agenda){e.preventDefault();$('#formerror').textContent='Isi peserta dan agenda meeting';return}let count=db.activities.length;old(e);if(db.activities.length>count){let a=db.activities[0];a.participants=p;a.meetingAgenda=agenda;record('Detail meeting',t.id,p)}}}};
function correction(kind,id){let x=kind==='lead'?db.leads.find(x=>x.id===id):db.activities.find(x=>x.id===id);modal('Ajukan koreksi data',area('Usulan koreksi','proposed',kind==='lead'?x.need:x.note,true)+area('Alasan','reason','',true)+`<p class="hint">Data sebelumnya tetap berlaku sampai supervisor memvalidasi.</p>`,f=>{db.corrections.push({id:uid('CR'),kind,record:id,proposed:f.proposed,reason:f.reason,owner:x.owner,status:'Menunggu',created:now()});record('Ajukan koreksi',id,f.reason)})}
function reviewCorrection(id,decision){if(!supervisors())return toast('Perlu supervisor');let cr=db.corrections.find(x=>x.id===id);modal('Validasi koreksi',area('Catatan keputusan','note','',true),f=>{if(cr.status!=='Menunggu')throw Error('Sudah diproses');if(decision==='Disetujui'){let x=cr.kind==='lead'?db.leads.find(x=>x.id===cr.record):db.activities.find(x=>x.id===cr.record);cr.before=cr.kind==='lead'?x.need:x.note;if(cr.kind==='lead')x.need=cr.proposed;else x.note=cr.proposed}cr.status=decision;cr.reviewed=now();cr.reviewer=actor();record('Validasi koreksi',cr.record,decision+' / '+f.note)})}
function applicationForm(oid='',id=''){let a=db.applications.find(x=>x.id===id)||{},o=opp(oid||a.opp);if(!o)return toast('Pilih opportunity dahulu');modal(id?'Update status pengajuan':'Tautkan pengajuan',`<p class="hint">Masukkan referensi pengajuan dan status terbaru berdasarkan informasi yang diterima.</p>`+field('Nomor pengajuan / referensi Bank','number',a.number||'','text',true)+field('Produk','product',a.product||o.product,'text',true)+select('Survey','survey',['Belum dimulai','Terjadwal','Dalam proses','Selesai','Tidak berlaku'],a.survey)+select('Analisa','analysis',['Belum dimulai','Dalam proses','Selesai','Perlu perbaikan','Tidak berlaku'],a.analysis)+select('Approval','approval',['Belum diputuskan','Dalam review','Disetujui','Ditolak','Tidak berlaku'],a.approval)+select('Pencairan / realisasi','disbursement',['Belum dicairkan','Dalam proses','Dicairkan','Tidak berlaku'],a.disbursement)+field('Sumber / referensi pembaruan','source',a.source||'Input manual','text',true)+area('Catatan perubahan','note','',true),f=>{if(db.applications.some(x=>x.id!==id&&x.number===f.number))throw Error('Nomor sudah ditautkan. Periksa pengajuan existing.');if(!id){a={id:uid('AP'),profile:o.profile,opp:o.id,history:[]};db.applications.push(a)}a.history.push({time:now(),actor:actor(),note:f.note,before:{survey:a.survey,analysis:a.analysis,approval:a.approval,disbursement:a.disbursement},after:{...f}});Object.assign(a,{...f,updated:now()});record('Update status pengajuan',a.id,f.number)})}
function applicationCard(a){let o=opp(a.opp);return `<article class="record"><div class="recordtop"><span class="label">REFERENSI PENGAJUAN</span>${badge('Input manual')}</div><h3>${E(a.number)}</h3><p>${E(pname(a.profile))} · ${E(a.product)}</p><div class="facts">${labelled('Survey',a.survey)}${labelled('Analisa',a.analysis)}${labelled('Approval',a.approval)}${labelled('Pencairan',a.disbursement)}</div><small>${fmt(a.updated)} · ${E(a.source)}</small><div class="actions">${btn('Update status',`applicationForm('${a.opp}','${a.id}')`)}${btn('Opportunity',`go('Opportunity detail','${a.opp}')`)}</div>${sectionToggle('Riwayat status',a.history.slice().reverse().map(x=>`<div class="miniitem"><b>${E(x.note)}</b><p>${fmt(x.time)} · ${E(x.actor)}</p>${x.after?`<small>${E(x.after.survey)} / ${E(x.after.analysis)} / ${E(x.after.approval)} / ${E(x.after.disbursement)}</small>`:''}</div>`).join(''))}</article>`}
function editProfile(id){let p=profile(id);modal('Lengkapi profil',field('Nama','name',p.name,'text',true)+field('Kontak','contact',p.contact)+field('Telepon','phone',p.phone,'tel',true)+field('Alamat','address',p.address)+field('Alamat usaha / tempat bekerja','businessAddress',p.businessAddress||'')+field('Pekerjaan / bidang usaha','occupation',p.occupation||'')+sectionToggle('Referensi identitas - opsional',field('CIF (jika tersedia)','cif',p.cif||'')+field('NIK (jika diperlukan)','nik',p.nik||'')),f=>{Object.assign(p,f);record('Update profil',id,'Informasi identitas')})}
function configForm(){if(!supervisors())return toast('Konfigurasi memerlukan supervisor/admin');modal('Parameter workflow',stages.map(s=>field('SLA tahap '+s+' (hari)','sla_'+s,db.config.stageSla[s],'number',true)).join('')+field('Hari kerja','workdays',db.config.workdays,'text',true)+field('Hari libur (YYYY-MM-DD, pisahkan koma)','holidays',db.config.holidays)+`<p class="hint">Atur batas waktu setiap tahap. Kalender menggunakan WITA.</p>`,f=>{for(let s of stages){let n=Number(f['sla_'+s]);if(!Number.isInteger(n)||n<1)throw Error('SLA minimal satu hari');db.config.stageSla[s]=n}db.config.workdays=f.workdays;db.config.holidays=f.holidays;record('Update parameter SLA','config',JSON.stringify(db.config.stageSla))})}
let calendarMonth=today().slice(0,7),calendarDate='';function calendarView(){let [year,mo]=calendarMonth.split('-').map(Number),days=new Date(year,mo,0).getDate(),start=(new Date(year,mo-1,1).getDay()+6)%7;return `<div class="panel"><div class="calendarhead"><h2>Kalender aktivitas</h2><input aria-label="Bulan kalender" type="month" value="${calendarMonth}" onchange="calendarMonth=this.value;calendarDate='';renderContent()"></div><div class="calendargrid">${['Sen','Sel','Rab','Kam','Jum','Sab','Min'].map(d=>`<small>${d}</small>`).join('')}${Array.from({length:start},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>{let d=calendarMonth+'-'+String(i+1).padStart(2,'0'),n=visible(db.tasks).filter(t=>t.scheduled.startsWith(d)&&isOpen(t)).length;return `<button class="${d===calendarDate?'selected':''} ${d===today()?'istoday':''}" onclick="calendarDate='${d}';renderContent()">${i+1}${n?`<i>${n}</i>`:''}</button>`}).join('')}</div>${calendarDate?`<div class="actions">${btn('Tampilkan semua tanggal',"calendarDate='';renderContent()")}</div>`:''}</div>`}
function downloadCsv(name,rows){let csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=name+'.csv';a.click();URL.revokeObjectURL(a.href)}
function exportReport(kind){if(kind==='Opportunity')downloadCsv('opportunity', [['ID','Nasabah','Nama','Stage','Status','Nilai','Basis','Probability','Closing','Owner'],...visible(db.opps).filter(o=>!month||o.created.startsWith(month)).map(o=>[o.id,pname(o.profile),o.name,o.stage,o.outcome,o.value,o.basis,o.probability,o.closing,o.owner])]);else if(kind==='Lead')downloadCsv('leads',[['ID','Nasabah','Sumber','Referral','Status','Qualification','Kategori','Owner'],...visible(db.leads).filter(l=>!month||l.created.startsWith(month)).map(l=>[l.id,pname(l.profile),l.source,l.referral,l.status,l.qualification,l.grade,l.owner])]);else downloadCsv('aktivitas',[['ID','Nasabah','Jenis','Hasil','Catatan','Waktu','Petugas'],...visible(db.activities).filter(a=>!month||a.occurred.startsWith(month)).map(a=>[a.id,pname(a.profile),a.type,a.result,a.note,a.occurred,a.owner])])}
function approvalScreen(){return titleBlock('Persetujuan','Rencana kunjungan, perubahan jadwal dan validasi koreksi.')+`<div class="records">${pendingApprovals().map(t=>`<article class="record"><div class="recordtop">${badge(t.approval)}<small>${E(t.owner)}</small></div><h3>${E(t.purpose)}</h3><p>${E(pname(t.profile))}</p><div class="meta">Jadwal saat ini ${fmt(t.scheduled)}${t.pendingChange?`<br>Usulan ${fmt(t.pendingChange.scheduled)}<br>Alasan: ${E(t.pendingChange.reason)}`:''}</div><div class="actions">${supervisors()?btn('Setujui',`approveVisit('${t.id}','Disetujui')`,true)+btn('Kembalikan',`approveVisit('${t.id}','Dikembalikan')`):''}${btn('Detail',`go('Aktivitas detail','${t.id}')`)}</div></article>`).join('')||empty('Tidak ada rencana menunggu persetujuan.')}</div><div class="panel"><h2>Koreksi data menunggu validasi</h2>${db.corrections.filter(x=>x.status==='Menunggu'&&mine(x)).map(x=>`<div class="miniitem"><b>${E(x.record)}</b><p>${E(x.reason)}</p><p>Usulan: ${E(x.proposed)}</p>${supervisors()?`<div class="actions">${btn('Validasi',`reviewCorrection('${x.id}','Disetujui')`,true)}${btn('Kembalikan',`reviewCorrection('${x.id}','Dikembalikan')`)}</div>`:''}</div>`).join('')||empty('Tidak ada koreksi menunggu.')}</div>`}
function notificationScreen(){let items=[];visible(db.tasks).filter(overdue).forEach(t=>items.push({title:'Follow-up melewati deadline',note:t.purpose+' · '+pname(t.profile),action:`go('Aktivitas detail','${t.id}')`}));visible(db.tasks).filter(t=>isOpen(t)&&!overdue(t)&&parseCRMDate(t.scheduled)-Date.now()<86400000).forEach(t=>items.push({title:'Pengingat agenda',note:t.purpose+' · '+fmt(t.scheduled),action:`go('Aktivitas detail','${t.id}')`}));visible(db.opps).filter(overSla).forEach(o=>items.push({title:'Eskalasi: opportunity over SLA',note:o.name+' · '+age(o)+' hari / SLA '+stageLimit(o)+' hari',action:`go('Opportunity detail','${o.id}')`}));pendingApprovals().forEach(t=>items.push({title:'Rencana menunggu keputusan',note:t.purpose,action:"go('Persetujuan')"}));return titleBlock('Pusat perhatian','Pantau pengingat agenda, keterlambatan dan permintaan persetujuan.')+`<div class="panel">${items.map(i=>`<button class="notifrow" onclick="${i.action}"><span class="notifdot"></span><span><strong>${E(i.title)}</strong><small>${E(i.note)}</small></span><b>↗</b></button>`).join('')||empty('Tidak ada notifikasi.')}</div>`}
function reportScreen(){let ls=visible(db.leads).filter(l=>!month||l.created.startsWith(month)),os=visible(db.opps).filter(o=>!month||o.created.startsWith(month)),won=os.filter(o=>o.outcome==='Won'),lost=os.filter(o=>o.outcome==='Lost');return titleBlock('Laporan operasional','Cohort lead/opportunity berdasarkan bulan dibuat. Export aktivitas berdasarkan waktu kejadian.')+`<div class="toolbar"><input aria-label="Periode laporan" type="month" value="${month}" onchange="month=this.value;renderContent()">${btn('Semua periode',"month='';renderContent()")}${btn('Cetak / simpan PDF','window.print()')}</div><div class="metrics">${[['Lead',ls.length],['Opportunity',os.length],['Won',won.length],['Lost',lost.length]].map(([a,b])=>`<div class="metric"><span>${a}</span><strong>${b}</strong></div>`).join('')}</div><div class="split"><div class="panel"><h2>Efektivitas sumber dan referral</h2>${[...new Set(ls.map(l=>l.source))].map(src=>{let a=ls.filter(l=>l.source===src);return `<div class="summaryrow"><strong>${E(src)}</strong><span>${a.length} lead · ${a.filter(l=>l.status==='Converted').length} converted</span></div>`}).join('')}<h2>Alasan lost</h2>${lost.map(o=>`<div class="miniitem"><b>${E(o.name)}</b><p>${E(o.reason||'-')}</p></div>`).join('')||empty('Belum ada opportunity lost.')}</div><div class="panel"><h2>Export data sesuai periode</h2><p>CSV dapat dibuka di Excel. Laporan PDF melalui dialog cetak browser.</p><div class="actions">${['Lead','Opportunity','Aktivitas'].map(k=>btn('Export '+k,`exportReport('${k}')`)).join('')}</div><p class="hint">Probability merupakan estimasi AO. Nilai pipeline mengikuti basis nilai masing-masing peluang.</p></div></div>`}
renderContent=function(){migrate();if(view==='Persetujuan'){$('#app').innerHTML=approvalScreen();return}if(view==='Notifikasi'){$('#app').innerHTML=notificationScreen();return}if(view==='Laporan'){$('#app').innerHTML=reportScreen();return}if(view==='Pengajuan'){$('#app').innerHTML=titleBlock('Tracking pengajuan','Nomor referensi, progres dan riwayat pengajuan.')+`<div class="records">${db.applications.filter(a=>mine(opp(a.opp))).map(applicationCard).join('')||empty('Buka detail opportunity untuk menautkan pengajuan.')}</div>`;return}originalContent();const app=$('#app');
if(view==='Monitoring'){let metric=app.querySelectorAll('.metric')[3];if(metric){metric.querySelector('strong').textContent=visible(db.opps).filter(overSla).length;metric.setAttribute('onclick',"go('Notifikasi')")}app.insertAdjacentHTML('afterbegin',`<div class="quicklinks">${btn('Persetujuan ('+pendingApprovals().length+')',"go('Persetujuan')")}${btn('Reminder & eskalasi',"go('Notifikasi')")}${btn('Laporan',"go('Laporan')")}</div>`)}
if(view==='Leads'){app.querySelectorAll('.record').forEach((el,i)=>{let b=el.querySelector('.textbtn');let id=b?.getAttribute('onclick')?.match(/'([^']+)'\)$/)?.[1],l=db.leads.find(x=>x.id===id);if(l)el.insertAdjacentHTML('beforeend',`<div class="oppmeta">${badge(l.grade)}<span>${E(l.qualification)}</span></div>`)});}
if(view==='Lead detail'){let l=db.leads.find(x=>x.id===focus);if(l&&mine(l)){let a=l.assessment;app.querySelector('.panel')?.insertAdjacentHTML('beforeend',`<div class="qualificationstrip">${badge(l.grade)}<span>${E(l.qualification)}</span><span>${E(l.potential||'Potensi belum dinilai')}</span></div><div class="actions">${btn('Survey & assessment',`assessment('${l.id}')`)}${btn('Ajukan koreksi data',`correction('lead','${l.id}')`)}</div>${a?sectionToggle('Hasil assessment',`<div class="facts">${labelled('Hasil survey',a.survey)}${labelled('Informasi usaha',a.business)}${labelled('Gambaran keuangan',a.financial)}${labelled('Kesimpulan',a.conclusion)}</div><small>${fmt(a.recorded)} · ${E(a.actor)}</small>`):'<p class="hint">Assessment awal belum diisi. Lengkapi setelah memperoleh informasi lead.</p>'}`)}}
if(view==='Opportunity detail'){let o=opp(focus);if(o&&mine(o)){app.querySelector('.panel')?.insertAdjacentHTML('beforeend',`<div class="qualificationstrip"><b>${o.probability??0}% probability</b><span>SLA tahap ${stageLimit(o)} hari</span>${badge(overSla(o)?'Over SLA':'Dalam SLA')}</div><small>Target bisnis: ${E(o.target||'Belum ditautkan')}</small><div class="actions">${btn('Edit detail peluang',`editOpportunity('${o.id}')`)}${btn('Tautkan pengajuan',`applicationForm('${o.id}')`)}</div>`);app.insertAdjacentHTML('beforeend',`<section class="panel"><h2>Pengajuan terkait</h2><p>Tracking proses Bank terpisah dari tahap pemasaran. Perubahan status tercatat pada histori pengajuan.</p>${db.applications.filter(a=>a.opp===o.id).map(applicationCard).join('')||empty('Belum ada nomor pengajuan. Opportunity tetap dapat berjalan.')}</section>`)}}
if(view==='Agenda'){app.insertAdjacentHTML('afterbegin',calendarView());if(calendarDate){let ts=visible(db.tasks).filter(t=>t.scheduled.startsWith(calendarDate));let rec=app.querySelector('.records');if(rec)rec.innerHTML=ts.map(taskCard).join('')||empty('Tidak ada agenda pada tanggal ini.')}}
if(view==='Aktivitas detail'){let t=task(focus);if(t&&mine(t)){if(activityKind(t.type)==='Kunjungan'){let panel=app.querySelector('.panel');panel?.insertAdjacentHTML('afterbegin',`<div class="approvalstrip">${badge(t.approval||'Menunggu')}<span>Persetujuan rencana kunjungan</span></div>`);let box=app.querySelector('.activitybox');if(box&&t.approval!=='Disetujui'){box.innerHTML=`<div class="approvalwait"><strong>${t.approval==='Dikembalikan'?'Perlu revisi rencana':'Menunggu persetujuan supervisor'}</strong><p>Check-in tersedia setelah rencana disetujui.</p><div class="actions">${supervisors()&&['Menunggu','Perubahan diajukan'].includes(t.approval)?btn('Review permintaan',"go('Persetujuan')",true):''}${btn('Ubah jadwal',`reschedule('${t.id}')`)}${t.approval==='Dikembalikan'?btn('Ajukan ulang',`resubmitVisit('${t.id}')`):''}</div></div>`}app.insertAdjacentHTML('beforeend',`<section class="panel"><h2>Riwayat persetujuan</h2>${(t.approvalHistory||[]).slice().reverse().map(a=>`<div class="miniitem"><b>${E(a.status)}</b><p>${E(a.note||'Tanpa catatan')}</p><small>${fmt(a.time)} · ${E(a.actor)}</small></div>`).join('')||empty('Belum ada keputusan.')}</section>`)}if(isOpen(t))app.querySelector('.panel')?.insertAdjacentHTML('beforeend',`<div class="actions">${btn('Batalkan aktivitas',`cancelTask('${t.id}')`)}</div>`);let a=db.activities.find(a=>a.task===t.id);if(a)app.insertAdjacentHTML('beforeend',`<section class="panel"><h2>Hasil tersimpan</h2><p>${E(a.note)}</p>${a.participants?`<p>Peserta: ${E(a.participants)}<br>Agenda: ${E(a.meetingAgenda)}</p>`:''}${btn('Ajukan koreksi',`correction('activity','${a.id}')`)}</section>`)}}
if(view==='Nasabah detail'){let p=profile(focus);if(p&&mine(p))app.querySelector('.panel')?.insertAdjacentHTML('beforeend',`<div class="actions">${btn('Lengkapi identitas',`editProfile('${p.id}')`)}</div>${sectionToggle('Identitas tambahan',`<div class="facts">${labelled('Alamat usaha',p.businessAddress)}${labelled('Pekerjaan',p.occupation)}${labelled('CIF',p.cif)}${labelled('NIK',p.nik)}</div>`)}`)}
if(view==='Lainnya'||view==='Pengaturan'){app.insertAdjacentHTML('afterbegin',`<section class="panel"><h2>Pusat kerja</h2><div class="menulist">${[['Persetujuan','Rencana dan perubahan kunjungan'],['Pengajuan','Nomor, status dan histori'],['Notifikasi','Reminder dan eskalasi SLA'],['Laporan','Referral, win/loss dan export']].map(([p,s])=>`<button onclick="go('${p}')"><strong>${p}</strong><small>${s}</small><span>↗</span></button>`).join('')}</div></section>`);app.insertAdjacentHTML('beforeend',`<section class="panel"><h2>SLA per tahap</h2>${stages.map(s=>`<div class="summaryrow"><b>${s}</b><span>${db.config.stageSla[s]} hari</span></div>`).join('')}<p class="hint">WITA · Aging dihitung dalam hari kalender.</p>${btn('Konfigurasi SLA','configForm()')}</section>`)}}
// Clearer labels on simulated forms and consistent persistence after migration.
localStorage.setItem(key,JSON.stringify(db));
let sourceFilter='',mobilePipeline='Daftar';
const previousContent=renderContent;
renderContent=function(){previousContent();let app=$('#app');if(view==='Leads'){let tb=app.querySelector('.toolbar');tb?.insertAdjacentHTML('beforeend',`<select aria-label="Sumber lead" onchange="sourceFilter=this.value;renderContent()"><option value="">Semua sumber</option>${[...new Set(db.leads.map(l=>l.source))].map(s=>`<option ${sourceFilter===s?'selected':''}>${E(s)}</option>`).join('')}</select>`);if(sourceFilter)app.querySelectorAll('.record').forEach(el=>{let src=el.querySelector('.recordtop .label')?.textContent;if(src!==sourceFilter)el.remove()})}if(mobile&&view==='Peluang'){app.querySelector('.toolbar')?.insertAdjacentHTML('afterend',`<div class="tabs">${['Daftar','Pipeline'].map(v=>`<button class="${mobilePipeline===v?'active':''}" onclick="mobilePipeline='${v}';renderContent()">${v}</button>`).join('')}</div>`);if(mobilePipeline==='Daftar'){let a=db.opps.filter(o=>matches(o,o.name+' '+pname(o.profile))&&(!month||o.created.startsWith(month))&&(!stageFilter||o.stage===stageFilter));let board=app.querySelector('.board');if(board){board.className='records';board.innerHTML=a.map(oppCard).join('')||empty('Tidak ada peluang sesuai filter.')}}}if(view==='Agenda'){app.insertAdjacentHTML('afterbegin',`<div class="agendainsight"><span><b>${visible(db.tasks).filter(t=>isOpen(t)&&t.scheduled.startsWith(today())).length}</b> agenda hari ini</span><span><b>${visible(db.tasks).filter(overdue).length}</b> overdue</span><button class="textbtn" onclick="go('Notifikasi')">Lihat pengingat ↗</button></div>`)} };
